/* Pixel palette: dark background, cream card, teal accent, coral highlight */
:root {
  --bg: #1a1a2e;
  --card: #f0e6d3;
  --ink: #16213e;
  --accent: #e94560;
  --accent2: #0f3460;
  --border: 4px solid var(--ink);
  --font: 'Courier New', Courier, monospace;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: linear-gradient(45deg, #1a1a2e 25%, transparent 25%),
                    linear-gradient(-45deg, #1a1a2e 25%, transparent 25%),
                    linear-gradient(45deg, transparent 75%, #1a1a2e 75%),
                    linear-gradient(-45deg, transparent 75%, #1a1a2e 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  font-family: var(--font);
  font-size: 16px;
  color: var(--ink);
  padding: 16px;
}
.card {
  background: var(--card);
  border: var(--border);
  box-shadow: 8px 8px 0 var(--accent2);
  padding: 24px;
  width: 100%;
  max-width: 400px;
  image-rendering: pixelated;
}
h1 {
  font-size: 1.5rem;
  text-align: center;
  margin-bottom: 20px;
  text-transform: uppercase;
  letter-spacing: 2px;
  border-bottom: var(--border);
  padding-bottom: 12px;
}
.field { margin-bottom: 16px; }
label {
  display: block;
  font-weight: bold;
  margin-bottom: 6px;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}
input, select {
  width: 100%;
  padding: 10px 12px;
  font-family: var(--font);
  font-size: 1rem;
  border: var(--border);
  background: #fff;
  color: var(--ink);
  outline: none;
}
input:focus, select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent);
}
button {
  width: 100%;
  padding: 12px;
  font-family: var(--font);
  font-size: 1.1rem;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 2px;
  background: var(--accent);
  color: #fff;
  border: var(--border);
  cursor: pointer;
  box-shadow: 4px 4px 0 var(--accent2);
  transition: transform 0.05s, box-shadow 0.05s;
}
button:hover { background: #ff5c7a; }
button:focus-visible { outline: 3px solid var(--ink); outline-offset: 2px; }
button:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 var(--accent2);
}
.result-box {
  margin-top: 20px;
  padding: 16px;
  border: var(--border);
  background: #fff;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}
.result-label {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  font-weight: bold;
}
#result {
  font-size: 2rem;
  font-weight: bold;
  min-height: 2.5rem;
  color: var(--accent2);
  word-break: break-all;
}
.formula {
  margin-top: 16px;
  font-size: 0.8rem;
  text-align: center;
  color: #555;
  line-height: 1.6;
}
@media (max-width: 400px) {
  .card { padding: 16px; }
  h1 { font-size: 1.2rem; }
  #result { font-size: 1.5rem; }
}

document.addEventListener('DOMContentLoaded', () => {
  const tempInput = document.getElementById('temperature');
  const direction = document.getElementById('direction');
  const convertBtn = document.getElementById('convert');
  const resultEl = document.getElementById('result');

  function convert() {
    const raw = tempInput.value.trim();
    const num = parseFloat(raw);
    if (raw === '' || !isFinite(num)) {
      resultEl.textContent = 'Error';
      return;
    }
    let result;
    if (direction.value === 'c-to-f') {
      result = num * 9 / 5 + 32;
    } else {
      result = (num - 32) * 5 / 9;
    }
    resultEl.textContent = result.toFixed(2);
  }

  convertBtn.addEventListener('click', convert);
  tempInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') convert();
  });
});
